/// The scopes that grant access. A protected resource advertises only these: MCP clients
/// that request every listed scope must not pick up a narrowing, which would make the
/// consent page start from a narrower access than they meant to ask for.
fn granting_scopes() -> Vec<String> {
    [
        "mcp:all",
        "mcp:favorites",
        "mcp:scripts:*",
        "mcp:flows:*",
        "mcp:endpoints:*",
    ]
    .map(String::from)
    .to_vec()
}

fn supported_scopes() -> Vec<String> {
    let mut scopes = granting_scopes();
    scopes.extend(["mcp:read_only", "mcp:read_run", "mcp:runnables_as_tools"].map(String::from));
    scopes
}

/// GET /.well-known/oauth-authorization-server/api/w/:workspace_id/mcp/oauth/server
///
/// `client_base_url` serves what the MCP client calls itself, `base_url` the authorization
/// endpoint the user's browser opens.
fn build_oauth_metadata(
    oauth_prefix: &str,
    base_url: &str,
    client_base_url: &str,
) -> AuthorizationMetadata {
    AuthorizationMetadata {
        issuer: format!("{}{}", client_base_url, oauth_prefix),
        authorization_endpoint: format!("{}{}/authorize", base_url, oauth_prefix),
        token_endpoint: format!("{}{}/token", client_base_url, oauth_prefix),
        registration_endpoint: Some(format!("{}/api/mcp/oauth/server/register", client_base_url)),
        scopes_supported: Some(supported_scopes()),
        response_types_supported: Some(vec!["code".to_string()]),
        grant_types_supported: Some(vec![
            "authorization_code".to_string(),
            "refresh_token".to_string(),
        ]),
        code_challenge_methods_supported: Some(vec!["S256".to_string()]),
    }
}

fn build_protected_resource_metadata(
    resource_path: &str,
    oauth_prefix: &str,
    base_url: &str,
) -> ProtectedResourceMetadata {
    // With an external issuer configured, clients sign in there: Windmill's own server keeps
    // honouring the tokens it issued, but no longer hands out new ones to MCP clients.
    let (authorization_server, scopes) = match super::external_idp::configured() {
        Some(idp) => (
            idp.issuer.clone(),
            super::external_idp::REQUESTED_SCOPES
                .split(' ')
                .map(str::to_string)
                .collect(),
        ),
        None => (format!("{}{}", base_url, oauth_prefix), granting_scopes()),
    };
    ProtectedResourceMetadata {
        resource: format!("{}{}", base_url, resource_path),
        authorization_servers: vec![authorization_server],
        scopes_supported: Some(scopes),
        bearer_methods_supported: Some(vec!["header".to_string()]),
    }
}

pub async fn workspaced_oauth_metadata(
    Path(workspace_id): Path<String>,
) -> Json<AuthorizationMetadata> {
    let base_url = BASE_URL.load();
    let oauth_prefix = format!("/api/w/{}/mcp/oauth/server", workspace_id);
    Json(build_oauth_metadata(&oauth_prefix, &base_url, &base_url))
}

/// GET /.well-known/oauth-protected-resource/api/mcp/w/:workspace_id/mcp
pub async fn protected_resource_metadata_by_path(
    Path(workspace_id): Path<String>,
) -> Json<ProtectedResourceMetadata> {
    let base_url = BASE_URL.load();
    let resource_path = format!("/api/mcp/w/{}/mcp", workspace_id);
    let oauth_prefix = format!("/api/w/{}/mcp/oauth/server", workspace_id);
    Json(build_protected_resource_metadata(
        &resource_path,
        &oauth_prefix,
        &base_url,
    ))
}

/// Schemes that a browser executes as script or uses to read local content. The
/// consent page navigates the user's browser to the registered redirect_uri
/// (`window.location` / anchor `href`), so accepting any of these turns dynamic
/// client registration into a stored-XSS / token-exfiltration primitive.
const DISALLOWED_REDIRECT_URI_SCHEMES: &[&str] =
    &["javascript", "data", "vbscript", "blob", "file"];

/// Validate a dynamically-registered redirect_uri.
///
/// RFC 7591 dynamic client registration is intentionally unauthenticated for MCP
/// interoperability, so the redirect_uri is the security boundary: it must be an
/// absolute URI (RFC 6749 §3.1.2) and must not use a browser-executable scheme.
fn validate_redirect_uri(uri: &str) -> Result<()> {
    let parsed = url::Url::parse(uri).map_err(|_| {
        Error::BadRequest(format!(
            "Invalid redirect_uri (must be an absolute URI): {uri}"
        ))
    })?;
    // `url` normalizes the scheme to lowercase ASCII.
    if DISALLOWED_REDIRECT_URI_SCHEMES.contains(&parsed.scheme()) {
        return Err(Error::BadRequest(format!(
            "redirect_uri scheme '{}' is not allowed",
            parsed.scheme()
        )));
    }
    Ok(())
}

/// POST /api/mcp/oauth/server/register - dynamic client registration
pub async fn oauth_register(
    Extension(db): Extension<DB>,
    Json(req): Json<ClientRegistrationRequest>,
) -> Result<(axum::http::StatusCode, Json<ClientRegistrationResponse>)> {
    if req.redirect_uris.is_empty() {
        return Err(Error::BadRequest(
            "At least one redirect_uri is required".to_string(),
        ));
    }

    for uri in &req.redirect_uris {
        validate_redirect_uri(uri)?;
    }

    let client_id = format!("mcp-client-{}", rd_string(16));

    sqlx::query!(
        "INSERT INTO mcp_oauth_server_client (client_id, client_name, redirect_uris)
         VALUES ($1, $2, $3)",
        client_id,
        req.client_name,
        &req.redirect_uris,
    )
    .execute(&db)
    .await
    .map_err(|e| Error::InternalErr(format!("Failed to register client: {}", e)))?;

    Ok((
        axum::http::StatusCode::CREATED,
        Json(ClientRegistrationResponse {
            client_id,
            client_secret: None,
            client_name: req.client_name,
            redirect_uris: req.redirect_uris,
        }),
    ))
}

