/// POST /api/w/:workspace_id/mcp/oauth/server/token - exchange code for token or refresh
pub async fn oauth_token(
    Extension(db): Extension<DB>,
    Form(req): Form<TokenRequest>,
) -> std::result::Result<Json<TokenResponse>, OAuthTokenError> {
    let db_error = |e: sqlx::Error| {
        tracing::error!("Database error issuing MCP OAuth token: {}", e);
        OAuthTokenError::server_error("Database error")
    };
    let owner = match req.grant_type.as_str() {
        "authorization_code" => sqlx::query_scalar!(
            "SELECT user_email FROM mcp_oauth_server_code WHERE code = $1",
            req.code
        )
        .fetch_optional(&db)
        .await
        .map_err(db_error)?,
        "refresh_token" => sqlx::query_scalar!(
            "SELECT user_email FROM mcp_oauth_refresh_token WHERE refresh_token = $1",
            req.refresh_token.as_deref().unwrap_or_default()
        )
        .fetch_optional(&db)
        .await
        .map_err(db_error)?,
        _ => {
            return Err(OAuthTokenError::unsupported_grant_type(
                "Supported grant types: authorization_code, refresh_token",
            ))
        }
    };
    let mut tx = db.begin().await.map_err(db_error)?;
    if let Some(email) = &owner {
        crate::users::lock_mcp_oauth_grants(&mut tx, email, false)
            .await
            .map_err(db_error)?;
    }
    let res = if req.grant_type == "authorization_code" {
        handle_authorization_code_grant(&mut tx, &req).await
    } else {
        handle_refresh_token_grant(&mut tx, &req).await
    };
    // Committed on error too, so a rejected exchange still consumes its code or refresh token.
    let committed = tx.commit().await;
    match (res, committed) {
        (Ok(res), Ok(())) => Ok(res),
        (Err(e), committed) => {
            if let Err(ce) = committed {
                tracing::error!("Failed to commit rejected MCP OAuth exchange: {}", ce);
            }
            Err(e)
        }
        (Ok(_), Err(e)) => Err(db_error(e)),
    }
}

/// Handle authorization_code grant type
async fn handle_authorization_code_grant(
    tx: &mut sqlx::PgConnection,
    req: &TokenRequest,
) -> std::result::Result<Json<TokenResponse>, OAuthTokenError> {
    let auth_code = match sqlx::query_as!(
        AuthorizationCode,
        "DELETE FROM mcp_oauth_server_code
         WHERE code = $1 AND expires_at > now()
         RETURNING code, client_id, user_email, workspace_id, scopes, redirect_uri,
                   code_challenge, code_challenge_method, super_admin",
        req.code
    )
    .fetch_optional(&mut *tx)
    .await
    {
        Ok(Some(code)) => code,
        Ok(None) => {
            return Err(OAuthTokenError::invalid_grant(
                "Invalid or expired authorization code",
            ));
        }
        Err(e) => {
            tracing::error!("Database error consuming auth code: {}", e);
            return Err(OAuthTokenError::server_error("Database error"));
        }
    };

    if auth_code.client_id != req.client_id {
        return Err(OAuthTokenError::invalid_grant("client_id mismatch"));
    }

    if auth_code.redirect_uri != req.redirect_uri {
        return Err(OAuthTokenError::invalid_grant("redirect_uri mismatch"));
    }

    let challenge = auth_code.code_challenge.as_ref().ok_or_else(|| {
        OAuthTokenError::invalid_grant("Authorization code missing PKCE challenge")
    })?;

    let verifier = req
        .code_verifier
        .as_ref()
        .ok_or_else(|| OAuthTokenError::invalid_request("code_verifier is required"))?;

    let method = auth_code.code_challenge_method.as_deref().unwrap_or("S256");
    if method != "S256" {
        return Err(OAuthTokenError::invalid_grant(
            "Only S256 PKCE method is supported",
        ));
    }

    if !validate_pkce_s256(verifier, challenge) {
        return Err(OAuthTokenError::invalid_grant("Invalid code_verifier"));
    }

    let access_token = [REDACTED];
    let access_token_hash = hash_token(&access_token);
    let access_token_prefix = access_token
        .get(..TOKEN_PREFIX_LEN)
        .unwrap_or(&access_token);
    let plaintext: Option<&str> = if MIN_VERSION_SUPPORTS_TOKEN_HASH.met().await {
        None
    } else {
        Some(&access_token)
    };
    let refresh_token = [REDACTED];
    let token_family = sqlx::types::Uuid::new_v4();
    let scopes = auth_code.scopes;

    // Create access token (rejects archived workspaces inline)
    let rows = sqlx::query!(
        "INSERT INTO token (token_hash, token_prefix, token, email, label, expiration, scopes, workspace_id, super_admin)
         SELECT $1::varchar, $2::varchar, $3::varchar, $4::varchar, $5::varchar, now() + ($6 || ' seconds')::interval, $7::text[], $8::varchar,
             $9::bool AND COALESCE((SELECT super_admin FROM password WHERE email = $4), false)
         WHERE NOT EXISTS(SELECT 1 FROM workspace WHERE id = $8 AND deleted = true)",
        access_token_hash,
        access_token_prefix,
        plaintext as Option<&str>,
        auth_code.user_email,
        format!("mcp-oauth-{}", auth_code.client_id),
        MCP_OAUTH_TOKEN_EXPIRATION_SECS.to_string(),
        &scopes,
        auth_code.workspace_id,
        auth_code.super_admin,
    )
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!("Failed to create access token: {}", e);
        OAuthTokenError::server_error("Failed to create access token")
    })?;
    if rows.rows_affected() == 0 {
        return Err(OAuthTokenError::invalid_grant(
            "Cannot create a token for an archived workspace",
        ));
    }

    // Create refresh token — store the hash of the access token so we can delete it later
    sqlx::query!(
        "INSERT INTO mcp_oauth_refresh_token
         (refresh_token, access_token_hash, client_id, user_email, workspace_id, scopes, token_family, expires_at, super_admin)
         VALUES ($1, $2, $3, $4, $5, $6, $7, now() + ($8 || ' seconds')::interval, $9)",
        refresh_token,
        access_token_hash,
        auth_code.client_id,
        auth_code.user_email,
        auth_code.workspace_id,
        &scopes,
        token_family,
        MCP_OAUTH_REFRESH_TOKEN_EXPIRATION_SECS.to_string(),
        auth_code.super_admin,
    )
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!("Failed to create refresh token: {}", e);
        OAuthTokenError::server_error("Failed to create refresh token")
    })?;

    Ok(Json(TokenResponse {
        access_token,
        token_type: "Bearer".to_string(),
        expires_in: MCP_OAUTH_TOKEN_EXPIRATION_SECS,
        scope: Some(scopes.join(" ")),
        refresh_token: [REDACTED],
    }))
}

/// Handle refresh_token grant type with token rotation and theft detection
async fn handle_refresh_token_grant(
    tx: &mut sqlx::PgConnection,
    req: &TokenRequest,
) -> std::result::Result<Json<TokenResponse>, OAuthTokenError> {
    let refresh_token_value = req
        .refresh_token
        .as_ref()
        .ok_or_else(|| OAuthTokenError::invalid_request("refresh_token is required"))?;

    if req.client_id.is_empty() {
        return Err(OAuthTokenError::invalid_request("client_id is required"));
    }

    // Atomically claim the refresh token by setting used_at in a single UPDATE.
    let token_row = match sqlx::query_as!(
        RefreshTokenRow,
        "UPDATE mcp_oauth_refresh_token
         SET used_at = now()
         WHERE refresh_token = $1
           AND client_id = $2
           AND used_at IS NULL
           AND NOT revoked
           AND expires_at > now()
         RETURNING id, refresh_token, access_token_hash, client_id, user_email, workspace_id,
                   scopes, token_family, created_at, expires_at, used_at, revoked, super_admin",
        refresh_token_value,
        req.client_id
    )
    .fetch_optional(&mut *tx)
    .await
    {
        Ok(Some(row)) => row,
        Ok(None) => {
            // Check for token reuse (theft detection) and revoke family if detected
            if let Ok(Some(family)) = sqlx::query_scalar!(
                "SELECT token_family FROM mcp_oauth_refresh_token
                 WHERE refresh_token = $1 AND used_at IS NOT NULL",
                refresh_token_value
            )
            .fetch_optional(&mut *tx)
            .await
            {
                tracing::warn!("Refresh token reuse detected, revoking family {:?}", family);
                let _ = sqlx::query!(
                    "UPDATE mcp_oauth_refresh_token SET revoked = TRUE WHERE token_family = $1",
                    family
                )
                .execute(&mut *tx)
                .await;
            }
            return Err(OAuthTokenError::invalid_grant("Invalid refresh token"));
        }
        Err(e) => {
            tracing::error!("Database error claiming refresh token: {}", e);
            return Err(OAuthTokenError::server_error("Database error"));
        }
    };

    // Delete old access token using the stored hash
    sqlx::query!(
        "DELETE FROM token WHERE token_hash = $1",
        token_row.access_token_hash
    )
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!("Failed to delete old access token: {}", e);
        OAuthTokenError::server_error("Database error")
    })?;

    // Generate new tokens
    let new_access_token = [REDACTED];
    let new_access_token_hash = hash_token(&new_access_token);
    let new_access_token_prefix = new_access_token
        .get(..TOKEN_PREFIX_LEN)
        .unwrap_or(&new_access_token);
    let new_plaintext: Option<&str> = if MIN_VERSION_SUPPORTS_TOKEN_HASH.met().await {
        None
    } else {
        Some(&new_access_token)
    };
    let new_refresh_token = [REDACTED];
    // Re-issues the already-approved (hence already-contained) scopes verbatim;
    // containment is enforced once at approval time, so no re-check here.
    let scopes = token_row.scopes;

    // Create new access token (rejects archived workspaces inline)
    let rows = sqlx::query!(
        "INSERT INTO token (token_hash, token_prefix, token, email, label, expiration, scopes, workspace_id, super_admin)
         SELECT $1::varchar, $2::varchar, $3::varchar, $4::varchar, $5::varchar, now() + ($6 || ' seconds')::interval, $7::text[], $8::varchar,
             $9::bool AND COALESCE((SELECT super_admin FROM password WHERE email = $4), false)
         WHERE NOT EXISTS(SELECT 1 FROM workspace WHERE id = $8 AND deleted = true)",
        new_access_token_hash,
        new_access_token_prefix,
        new_plaintext as Option<&str>,
        token_row.user_email,
        format!("mcp-oauth-{}", token_row.client_id),
        MCP_OAUTH_TOKEN_EXPIRATION_SECS.to_string(),
        &scopes,
        token_row.workspace_id,
        token_row.super_admin,
    )
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!("Failed to create new access token: {}", e);
        OAuthTokenError::server_error("Failed to create access token")
    })?;
    if rows.rows_affected() == 0 {
        return Err(OAuthTokenError::invalid_grant(
            "Cannot create a token for an archived workspace",
        ));
    }

    // Create new refresh token (same token family for tracking) — store hash of access token
    sqlx::query!(
        "INSERT INTO mcp_oauth_refresh_token
         (refresh_token, access_token_hash, client_id, user_email, workspace_id, scopes, token_family, expires_at, super_admin)
         VALUES ($1, $2, $3, $4, $5, $6, $7, now() + ($8 || ' seconds')::interval, $9)",
        new_refresh_token,
        new_access_token_hash,
        token_row.client_id,
        token_row.user_email,
        token_row.workspace_id,
        &scopes,
        token_row.token_family,
        MCP_OAUTH_REFRESH_TOKEN_EXPIRATION_SECS.to_string(),
        token_row.super_admin,
    )
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!("Failed to create new refresh token: {}", e);
        OAuthTokenError::server_error("Failed to create refresh token")
    })?;

    Ok(Json(TokenResponse {
        access_token: [REDACTED],
        token_type: "Bearer".to_string(),
        expires_in: MCP_OAUTH_TOKEN_EXPIRATION_SECS,
        scope: Some(scopes.join(" ")),
        refresh_token: [REDACTED],
    }))
}

/// Shared authorize logic — validates params, looks up client, redirects to consent page.
/// When `workspace_id` is Some, passes it to frontend; when None, passes `gateway=true`.
async fn oauth_authorize_inner(
    db: &DB,
    params: AuthorizeQuery,
    workspace_id: Option<String>,
) -> axum::response::Response {
    let client = match sqlx::query_as!(
        OAuthClient,
        "SELECT client_id, client_name, redirect_uris FROM mcp_oauth_server_client WHERE client_id = $1",
        params.client_id
    )
    .fetch_optional(db)
    .await
    {
        Ok(Some(client)) => client,
        Ok(None) => {
            return OAuthJsonError::new("invalid_client", Some("Unknown client_id"))
                .into_response();
        }
        Err(e) => {
            tracing::error!("Database error looking up client: {}", e);
            return OAuthJsonError::new("server_error", Some("Database error"))
                .into_response();
        }
    };

    if !client.redirect_uris.contains(&params.redirect_uri) {
        return OAuthJsonError::new(
            "invalid_request",
            Some("redirect_uri does not match registered URIs"),
        )
        .into_response();
    }

    if params.response_type != "code" {
        return OAuthErrorRedirect::new(
            &params.redirect_uri,
            "unsupported_response_type",
            Some("Only 'code' response type is supported"),
            params.state.as_deref(),
        )
        .into_response();
    }

    let code_challenge = match &params.code_challenge {
        Some(challenge) if !challenge.is_empty() => challenge.as_str(),
        _ => {
            return OAuthErrorRedirect::new(
                &params.redirect_uri,
                "invalid_request",
                Some("PKCE required: code_challenge parameter is mandatory"),
                params.state.as_deref(),
            )
            .into_response();
        }
    };

    let code_challenge_method = params.code_challenge_method.as_deref().unwrap_or("S256");

    if code_challenge_method != "S256" {
        return OAuthErrorRedirect::new(
            &params.redirect_uri,
            "invalid_request",
            Some("Invalid code_challenge_method: only 'S256' is supported"),
            params.state.as_deref(),
        )
        .into_response();
    }

    let resource = match &params.resource {
        Some(r) => r,
        None => {
            return OAuthErrorRedirect::new(
                &params.redirect_uri,
                "invalid_request",
                Some("Missing 'resource' parameter. Required for MCP audience binding."),
                params.state.as_deref(),
            )
            .into_response();
        }
    };

    // Build frontend redirect params — gateway mode vs workspace mode
    let (mode_key, mode_value) = match &workspace_id {
        Some(w_id) => ("workspace_id", w_id.as_str()),
        None => ("gateway", "true"),
    };

    let base_url = BASE_URL.load();
    let frontend_url = format!(
        "{}/oauth/mcp_authorize?{}",
        base_url,
        serde_urlencoded::to_string(&[
            (mode_key, mode_value),
            ("client_id", params.client_id.as_str()),
            ("client_name", client.client_name.as_str()),
            ("redirect_uri", params.redirect_uri.as_str()),
            ("scope", params.scope.as_deref().unwrap_or("mcp:all")),
            ("state", params.state.as_deref().unwrap_or("")),
            ("code_challenge", code_challenge),
            ("code_challenge_method", code_challenge_method),
            ("resource", resource),
        ])
        .unwrap_or_default()
    );

    Redirect::temporary(&frontend_url).into_response()
}

/// Shared approve logic — validates form, checks membership, stores auth code.
async fn ensure_member(db: &DB, workspace_id: &str, email: &str) -> Result<()> {
    let is_member = sqlx::query_scalar!(
        "SELECT EXISTS(SELECT 1 FROM usr WHERE workspace_id = $1 AND email = $2 AND NOT disabled)",
        workspace_id,
        email
    )
    .fetch_one(db)
    .await
    .map_err(|e| Error::InternalErr(format!("Database error: {}", e)))?
    .unwrap_or(false);

    if !is_member {
        return Err(Error::NotAuthorized(format!(
            "User is not a member of workspace '{workspace_id}'"
        )));
    }
    Ok(())
}

/// `workspace_id` is the workspace the minted token is bound to; without one, the token
/// reaches what its scopes allow (`mcp:workspaces:`), or every workspace of its owner.
async fn oauth_approve_inner(
    db: &DB,
    authed: &ApiAuthed,
    workspace_id: Option<&str>,
    form: ApprovalForm,
) -> Result<Json<ApprovalResponse>> {
    // The code approved here is exchanged for a database token carrying only this
    // email, so an elevated job token would launder its identity into a credential
    // with no `job_id` — and the MCP gateway would then re-enter the API uncapped
    // (GHSA-hfh4-cx4h-3fcr). Guarded at the shared inner fn: both the workspaced and
    // the gateway approve route reach the exchange through here.
    forbid_elevated_job_token(db, &authed.email, authed.job_id).await?;

    let caller_restricted = authed
        .scopes
        .as_deref()
        .is_some_and(|s| s.iter().any(|x| !x.starts_with("if_jobs:filter_tags:")));
    if form.super_admin {
        windmill_api_auth::require_super_admin(db, authed).await?;
        // The owner's role is not the credential's: an MCP token minted without superadmin
        // access may approve a narrower token, never one carrying that access.
        if caller_restricted {
            return Err(Error::NotAuthorized(
                "Only an interactive session can grant superadmin access".to_string(),
            ));
        }
    } else if let Some(workspace_id) = workspace_id {
        ensure_member(db, workspace_id, &authed.email).await?;
    }

    // Verify client exists and redirect_uri is registered
    let client = sqlx::query_as!(
        OAuthClient,
        "SELECT client_id, client_name, redirect_uris FROM mcp_oauth_server_client WHERE client_id = $1",
        form.client_id
    )
    .fetch_optional(db)
    .await
    .map_err(|e| Error::InternalErr(format!("Database error: {}", e)))?
    .ok_or_else(|| Error::BadRequest("Unknown client_id".to_string()))?;

    if !client.redirect_uris.contains(&form.redirect_uri) {
        return Err(Error::BadRequest(
            "Invalid redirect_uri for this client".to_string(),
        ));
    }

    if form.code_challenge.is_empty() {
        return Err(Error::BadRequest(
            "PKCE required: code_challenge is mandatory".to_string(),
        ));
    }

    if form.code_challenge_method.is_empty() {
        return Err(Error::BadRequest(
            "PKCE required: code_challenge_method is mandatory".to_string(),
        ));
    }

    if form.code_challenge_method != "S256" {
        return Err(Error::BadRequest(
            "Invalid code_challenge_method: only 'S256' is supported".to_string(),
        ));
    }

    let code = format!("mcp-code-{}", rd_string(32));

    let mut scopes: Vec<String> = form
        .scope
        .split_whitespace()
        .map(|s| s.to_string())
        .collect();
    if scopes.iter().any(|s| s == "mcp:all") && !scopes.iter().any(|s| s == SESSION_SCOPE) {
        scopes.push(SESSION_SCOPE.to_string());
    }

    // The approver's own token bounds what it may grant: a scope-restricted MCP
    // token must not approve a broader one (e.g. mcp:scripts:f/x -> mcp:all). An
    // unrestricted approver (interactive session, scopes None) grants freely,
    // which is the normal consent flow. This is the legitimate MCP-narrowing
    // path, so it uses MCP-pattern containment rather than the byte-identical
    // rule ensure_scopes_within_caller applies on the generic token endpoints.
    if caller_restricted {
        // An empty grant would mint a token the auth layer treats as unscoped
        // (full privileges), so a restricted approver must not produce one.
        if scopes.is_empty() {
            return Err(Error::NotAuthorized(
                "A scope-restricted token cannot approve an empty scope grant".to_string(),
            ));
        }
        if scopes.iter().any(|s| !s.starts_with("mcp:")) {
            return Err(Error::NotAuthorized(
                "A scope-restricted token can only approve MCP (mcp:*) scopes".to_string(),
            ));
        }
        let caller_config = parse_mcp_scopes(authed.scopes.as_deref().unwrap_or(&[]))
            .map_err(|e| Error::InternalErr(format!("Failed to parse caller MCP scopes: {e}")))?;
        let requested_config = parse_mcp_scopes(&scopes)
            .map_err(|e| Error::BadRequest(format!("Failed to parse requested MCP scopes: {e}")))?;
        if !caller_config.contains(&requested_config) {
            return Err(Error::NotAuthorized(
                "Requested scopes exceed the approving token's own MCP scopes".to_string(),
            ));
        }
    }

    sqlx::query!(
        "INSERT INTO mcp_oauth_server_code
         (code, client_id, user_email, workspace_id, scopes, redirect_uri, code_challenge, code_challenge_method, super_admin)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)",
        code,
        form.client_id,
        authed.email,
        workspace_id,
        &scopes,
        form.redirect_uri,
        &form.code_challenge,
        &form.code_challenge_method,
        form.super_admin,
    )
    .execute(db)
    .await
    .map_err(|e| Error::InternalErr(format!("Failed to store authorization code: {}", e)))?;

    Ok(Json(ApprovalResponse {
        code,
        state: if form.state.is_empty() {
            None
        } else {
            Some(form.state)
        },
    }))
}

