#[cfg(test)]
mod tests {
    use super::{build_oauth_metadata, validate_redirect_uri};

    #[test]
    fn authorization_endpoint_stays_on_base_url() {
        let m = build_oauth_metadata(
            "/api/mcp/gateway/oauth/server",
            "https://private.corp",
            "https://mcp.example.com",
        );
        assert_eq!(
            m.issuer,
            "https://mcp.example.com/api/mcp/gateway/oauth/server"
        );
        assert_eq!(
            m.token_endpoint,
            "https://mcp.example.com/api/mcp/gateway/oauth/server/token"
        );
        assert_eq!(
            m.registration_endpoint.as_deref(),
            Some("https://mcp.example.com/api/mcp/oauth/server/register")
        );
        assert_eq!(
            m.authorization_endpoint,
            "https://private.corp/api/mcp/gateway/oauth/server/authorize"
        );
    }

    #[test]
    fn accepts_legitimate_redirect_uris() {
        for uri in [
            "https://app.example.com/oauth/callback",
            "http://localhost:9876/callback",
            "http://127.0.0.1:33418/oauth/callback",
            // Native/editor MCP clients use private-use URI schemes (RFC 8252).
            "vscode://anthropic.claude/oauth/callback",
            "cursor://anysphere.cursor/callback",
        ] {
            assert!(
                validate_redirect_uri(uri).is_ok(),
                "expected {uri} to be accepted"
            );
        }
    }

    #[test]
    fn rejects_browser_executable_and_relative_redirect_uris() {
        for uri in [
            // GHSA-q9xg-f2v2-695g: stored-XSS / token exfiltration via consent page.
            "javascript:fetch('/api/w/admins/tokens/create',{method:'POST'})//",
            "JavaScript:alert(document.domain)",
            "data:text/html,<script>alert(1)</script>",
            "vbscript:msgbox(1)",
            "blob:https://example.com/uuid",
            "file:///etc/passwd",
            // Not an absolute URI (RFC 6749 §3.1.2).
            "/relative/callback",
            "not a uri",
        ] {
            assert!(
                validate_redirect_uri(uri).is_err(),
                "expected {uri} to be rejected"
            );
        }
    }
}

